      "keep.8": "Desire is a skill I can keep developing",
      "keep.9": "Exploring pleasure together brings us closer",
      "loosen.1.belief": "I might not be good at this",
      "loosen.1.shift": "Presence matters more than getting it perfect",
      "loosen.2.belief": "If I ask questions, I'll look inexperienced",
      "loosen.2.shift": "Curiosity is attractive, not embarrassing",
      "loosen.3.belief": "I need a partner to lead me",
      "loosen.3.shift": "I can lead even while I'm still learning",
